def aggregate_inventory(items):
    totals = {}
    for index, item in enumerate(items):
        if not isinstance(item, dict):
            raise ValueError(f"item {index} must be an object")
        if not isinstance(item.get("sku"), str) or not item["sku"]:
            raise ValueError(f"item {index} has an invalid sku")
        quantity = item.get("quantity")
        if isinstance(quantity, bool) or not isinstance(quantity, int) or quantity < 0:
            raise ValueError(f"item {index} has an invalid quantity")
        sku = item["sku"]
        totals[sku] = totals.get(sku, 0) + quantity
    return [
        {"sku": sku, "quantity": totals[sku]}
        for sku in sorted(totals)
    ]

def aggregate_available(inventory, reservations):
    stock = {}
    reserved = {}

    def add(records, target, label):
        for index, record in enumerate(records):
            if not isinstance(record, dict):
                raise ValueError(f"{label} item {index} must be an object")
            sku = record.get("sku")
            quantity = record.get("quantity")
            if not isinstance(sku, str) or not sku:
                raise ValueError(f"{label} item {index} has an invalid sku")
            if isinstance(quantity, bool) or not isinstance(quantity, int) or quantity < 0:
                raise ValueError(f"{label} item {index} has an invalid quantity")
            target[sku] = target.get(sku, 0) + quantity

    add(inventory, stock, "inventory")
    add(reservations, reserved, "reservation")
    for sku, quantity in reserved.items():
        if sku not in stock or quantity > stock[sku]:
            raise ValueError(f"reservation exceeds stock for {sku}")
    return [
        {"sku": sku, "available": stock[sku] - reserved.get(sku, 0)}
        for sku in sorted(stock)
    ]
